        const e = 0.04, pos = new Float64Array(n * 3), nr = new Float64Array(n * 3), mat = new Int16Array(n), tone = new Int16Array(n);
        const pid = new Int16Array(n), d1 = new Float64Array(n), d2 = new Float64Array(n);
