    Object.assign(G, {
        deg, V, nrm, I3, Rx, Ry, Rz, mm3, mv3, tmv3, col3, fromCols, M4, mm4, pt4, lookRot, arange, rint,
        Prim, Sphere, Ellipsoid, RoundCone, RoundBox, CapCone, Part, bake, Camera, hexrgb,
    });
